<script setup>import {useForm} from '@inertiajs/vue3'; import {computed} from 'vue'; import AppLayout from '../../../Layouts/AppLayout.vue'; const props=defineProps({accounts:Array,endpoints:Object}); const line=()=>({account_id:'',detail:'',debit:'',credit:''}); const form=useForm({date:new Date().toISOString().slice(0,10),concept:'',reference:'',notes:'',lines:[line(),line()]}); const debit=computed(()=>form.lines.reduce((n,l)=>n+Number(l.debit||0),0)); const credit=computed(()=>form.lines.reduce((n,l)=>n+Number(l.credit||0),0));</script>
<template><AppLayout title="Nuevo asiento" eyebrow="Contabilidad" description="El asiento se guardará en borrador y debe estar balanceado."><form class="space-y-4" @submit.prevent="form.post(endpoints.store)"><section class="card p-5"><div class="grid gap-4 md:grid-cols-3"><label class="field-label">Fecha<input v-model="form.date" type="date" class="control"></label><label class="field-label md:col-span-2">Concepto<input v-model="form.concept" class="control"></label><label class="field-label">Referencia<input v-model="form.reference" class="control"></label><label class="field-label md:col-span-2">Notas<input v-model="form.notes" class="control"></label></div></section><section class="card overflow-hidden"><div class="section-heading flex justify-between"><h2 class="font-semibold">Líneas</h2><button type="button" class="btn-soft" @click="form.lines.push(line())">Agregar línea</button></div><div v-for="(row,i) in form.lines" :key="i" class="grid gap-3 border-b p-4 md:grid-cols-[1fr_1fr_140px_140px_auto]"><select v-model="row.account_id" class="control"><option value="">Cuenta</option><option v-for="account in accounts" :key="account.id" :value="account.id">{{account.code}} · {{account.name}}</option></select><input v-model="row.detail" class="control" placeholder="Detalle"><input v-model="row.debit" type="number" step=".01" min="0" class="control" placeholder="Debe"><input v-model="row.credit" type="number" step=".01" min="0" class="control" placeholder="Haber"><button v-if="form.lines.length>2" type="button" class="text-rose-600" @click="form.lines.splice(i,1)">×</button></div><div class="flex justify-end gap-6 p-4 text-sm"><span>Debe: C$ {{debit.toFixed(2)}}</span><span>Haber: C$ {{credit.toFixed(2)}}</span><strong :class="debit===credit?'text-emerald-700':'text-rose-600'">Diferencia: {{(debit-credit).toFixed(2)}}</strong></div></section><p v-if="Object.keys(form.errors).length" class="text-xs text-rose-600">{{Object.values(form.errors).join(' · ')}}</p><button class="btn-primary">Guardar borrador</button></form></AppLayout></template>
